import{_ as o,o as s,c as t,a as i}from"./app.DLiRGumz.js";const u=JSON.parse('{"title":"Setup Restore — Long-term Fixes Applied","description":"","frontmatter":{},"headers":[],"relativePath":"SETUP-RESTORE.md","filePath":"SETUP-RESTORE.md","lastUpdated":1771753292000}'),a={name:"SETUP-RESTORE.md"};function n(l,e,r,d,c,h){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="setup-restore-—-long-term-fixes-applied" tabindex="-1">Setup Restore — Long-term Fixes Applied <a class="header-anchor" href="#setup-restore-—-long-term-fixes-applied" aria-label="Permalink to &quot;Setup Restore — Long-term Fixes Applied&quot;">​</a></h1><h2 id="summary-of-changes" tabindex="-1">Summary of Changes <a class="header-anchor" href="#summary-of-changes" aria-label="Permalink to &quot;Summary of Changes&quot;">​</a></h2><h3 id="_1-thegent-shims-mtsp-10" tabindex="-1">1. <strong>thegent Shims (MTSP-10)</strong> <a class="header-anchor" href="#_1-thegent-shims-mtsp-10" aria-label="Permalink to &quot;1. **thegent Shims (MTSP-10)**&quot;">​</a></h3><p><strong>Purpose:</strong> Tool accelerators for optimization and multi-tenant coordination.</p><ul><li><strong>Git shim</strong> (<code>~/.local/bin/git</code>): Wraps git to inject hooks from <code>thegent/hooks/lib/common.sh</code> — multi-tenant lock coordination, index.lock contention handling, git_cached for read-only ops.</li><li><strong>Tool accelerators:</strong> grep→rg, find→fd, jq→jaq, uv (faster alternatives).</li><li><strong>Agent accelerators (NEW):</strong> <code>codex</code> and <code>copilot</code> — exec real binaries directly to avoid: <ul><li>zsh parsing Node.js scripts (copilot <code>/*---</code> glob error)</li><li>git subcommand routing (<code>git codex</code> / <code>git copilot</code> not a git command)</li></ul></li><li><strong>Role accelerators:</strong> run, bg, ps, logs, etc. → <code>thegent {role}</code>.</li></ul><p><strong>PATH:</strong> <code>~/.local/bin</code> must be early in PATH (first). Your <code>~/.zshenv</code> sets this.</p><h3 id="_2-copilot-parse-error-fixed" tabindex="-1">2. <strong>Copilot Parse Error (Fixed)</strong> <a class="header-anchor" href="#_2-copilot-parse-error-fixed" aria-label="Permalink to &quot;2. **Copilot Parse Error (Fixed)**&quot;">​</a></h3><p>The copilot script is a Node.js binary. When invoked as <code>zsh /opt/homebrew/bin/copilot</code>, zsh tries to parse it and fails on <code>/*---</code> (glob). <strong>Fix:</strong> thegent shims in <code>~/.local/bin</code> exec the real binary directly via bash, so the shebang is respected. Run <code>copilot</code> (not <code>zsh copilot</code>).</p><h3 id="_3-codex-copilot-git-routing-fixed" tabindex="-1">3. <strong>Codex / Copilot Git Routing (Fixed)</strong> <a class="header-anchor" href="#_3-codex-copilot-git-routing-fixed" aria-label="Permalink to &quot;3. **Codex / Copilot Git Routing (Fixed)**&quot;">​</a></h3><p>Same fix: thegent agent shims ensure <code>codex</code> and <code>copilot</code> resolve to the real binaries in <code>~/.local/bin</code> (before homebrew), and they <code>exec</code> directly — no git involvement.</p><p><strong>If you see</strong> <code>git: &#39;/opt/homebrew/bin/codex&#39; is not a git command</code> when running <code>codex</code>:</p><ol><li><p><strong>Install shell + shims:</strong></p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">thegent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shell</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">thegent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install-shims</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div></li><li><p><strong>Reload shell:</strong> <code>exec zsh</code> (or open a new terminal)</p></li><li><p><strong>Verify:</strong> <code>which codex</code> should show <code>~/.local/bin/codex</code> (not <code>/opt/homebrew/bin/codex</code>)</p></li><li><p><strong>If still wrong:</strong> Check PATH — <code>echo $PATH</code> must have <code>~/.local/bin</code> first. Your <code>~/.zshenv</code> should set this. Run <code>thegent doctor</code> to verify.</p></li></ol><h3 id="_4-zsh-setup-restored" tabindex="-1">4. <strong>Zsh Setup Restored</strong> <a class="header-anchor" href="#_4-zsh-setup-restored" aria-label="Permalink to &quot;4. **Zsh Setup Restored**&quot;">​</a></h3><ul><li><strong>~/.zshenv</strong> — Restored from <code>thegent/shell/.zshenv</code>. Sets PATH, sources <code>~/.zsh_bundle.zsh</code>.</li><li><strong>~/.zshrc</strong> — Restored from <code>thegent/shell/.zshrc</code>. Sources zshenv and bundle.</li><li><strong>~/.zsh_bundle.zsh</strong> — Replaced with thegent minimal (68 lines). Your previous 150KB bundle referenced missing files (zsh-nvm-x, prompt.zsh, providers/*, zsh-alias-hinter, fzf-tab, etc.). Backup: <code>~/.zsh_bundle.zsh.broken</code> if you created one.</li></ul><p><strong>Full shell setup:</strong> Run:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">thegent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shell</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>This installs:</p><ul><li><code>~/.zshenv</code>, <code>~/.zshrc</code>, <code>~/.zsh_bundle.zsh</code> (thegent core)</li><li><code>~/.zshrc.local</code> from template (when missing)</li><li>Zsh plugins: fzf-tab, zsh-autosuggestions, fast-syntax-highlighting</li></ul><p>Use <code>--no-plugins</code> to skip plugin install. Verify with <code>thegent doctor</code>.</p><p><strong>To restore custom modules:</strong> Use the proper long-term setup:</p><ol><li>Run <code>./scripts/install_zsh_plugins.sh</code> to install fzf-tab, autosuggestions, etc.</li><li>Copy <code>shell/zshrc.local.template</code> to <code>~/.zshrc.local</code> (or let the script do it)</li><li>See <strong><a href="./guides/SHELL_ZSH_PLUGIN_SETUP.html">SHELL_ZSH_PLUGIN_SETUP.md</a></strong> for fnm/mise (nvm replacement), starship/p10k, and troubleshooting</li></ol><h3 id="_5-ghostty-config" tabindex="-1">5. <strong>Ghostty Config</strong> <a class="header-anchor" href="#_5-ghostty-config" aria-label="Permalink to &quot;5. **Ghostty Config**&quot;">​</a></h3><p>Created <code>~/.config/ghostty/config</code>:</p><ul><li>Shell: <code>/bin/zsh -l</code> (login shell, loads ~/.zshenv)</li><li>Theme: one-dark</li><li>Font: JetBrains Mono 13</li><li>Cursor: bar, blink</li></ul><p>Reload: <code>cmd+shift+,</code> (macOS).</p><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="find-illegal-option-o-find-illegal-option-q" tabindex="-1">&quot;find: illegal option -- o&quot; / &quot;find: illegal option -- q&quot; <a class="header-anchor" href="#find-illegal-option-o-find-illegal-option-q" aria-label="Permalink to &quot;&quot;find: illegal option -- o&quot; / &quot;find: illegal option -- q&quot;&quot;">​</a></h3><p><strong>Cause:</strong> find shim or fd-wrapper was passing find args to fd. <strong>Fixed</strong> in fd-wrapper.sh and install find shim:</p><ul><li>Complex find args (-o, -name, -path, -print, -quit, etc.) now use <code>command find</code> (real find)</li><li>Find shim only routes to fd when called with a single path (e.g. <code>find .</code>)</li></ul><h3 id="fork-resource-temporarily-unavailable" tabindex="-1">&quot;fork: Resource temporarily unavailable&quot; <a class="header-anchor" href="#fork-resource-temporarily-unavailable" aria-label="Permalink to &quot;&quot;fork: Resource temporarily unavailable&quot;&quot;">​</a></h3><p><strong>Cause:</strong> Process limit hit (too many hooks/subprocesses). <strong>Mitigations:</strong></p><ul><li>Set <code>THEGENT_HOOKS_MINIMAL=1</code> to skip lightweight advisory hooks (e.g. session-start-pending-notice)</li><li>Close other terminals/IDEs to free processes</li><li>Run <code>ulimit -u</code> to check process limit; increase if needed</li></ul><h3 id="eval-1-command-not-found-optimization-initiative-complete-md" tabindex="-1">&quot;(eval):1: command not found: OPTIMIZATION_INITIATIVE_COMPLETE.md&quot; <a class="header-anchor" href="#eval-1-command-not-found-optimization-initiative-complete-md" aria-label="Permalink to &quot;&quot;(eval):1: command not found: OPTIMIZATION_INITIATIVE_COMPLETE.md&quot;&quot;">​</a></h3><p><strong>Cause:</strong> Something is <code>eval</code>&#39;ing output that contains file paths (each line executed as a command). Check your <code>.zshrc</code> / <code>.zshenv</code> for <code>eval $(...)</code> that might output paths. Avoid eval&#39;ing find/grep output directly.</p><h3 id="no-such-option-e" tabindex="-1">&quot;No such option: -e&quot; <a class="header-anchor" href="#no-such-option-e" aria-label="Permalink to &quot;&quot;No such option: -e&quot;&quot;">​</a></h3><p><strong>Cause:</strong> Option conflict or wrong tool. With <code>thegent install</code>, <code>-e</code> is short for <code>--editable</code>. If you see this from another command (e.g. codex, copilot), that tool may not support <code>-e</code>.</p><h3 id="no-such-option-force-on-dex-native-force" tabindex="-1">&quot;No such option: --force&quot; on <code>dex --native --force</code> <a class="header-anchor" href="#no-such-option-force-on-dex-native-force" aria-label="Permalink to &quot;&quot;No such option: --force&quot; on \`dex --native --force\`&quot;">​</a></h3><p><strong>Cause:</strong> You are hitting a stale <code>dex</code> shim tied to an older CLI surface. The current shim path expects <code>--force-yolo</code> for force behavior.</p><p><strong>Fix:</strong></p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">thegent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install-shims</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zsh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # or open a new terminal</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">thegent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>If <code>which dex</code> does not point at <code>~/.local/bin/dex</code>, reload PATH to prioritize <code>~/.local/bin</code> and retry.</p><h3 id="ps-aux-or-ps-ef-hangs-130-seconds-shell-commands-very-slow" tabindex="-1">&quot;ps aux&quot; or &quot;ps -ef&quot; hangs 130+ seconds / shell commands very slow <a class="header-anchor" href="#ps-aux-or-ps-ef-hangs-130-seconds-shell-commands-very-slow" aria-label="Permalink to &quot;&quot;ps aux&quot; or &quot;ps -ef&quot; hangs 130+ seconds / shell commands very slow&quot;">​</a></h3><p><strong>Cause:</strong> A legacy <code>~/.local/bin/ps</code> shim (thegent role accelerator) shadows the system <code>ps</code>. When agents or users run <code>ps aux</code>, they invoke <code>thegent ps</code> (Python CLI for agent sessions) instead of the system process list — which hangs waiting for MCP/API.</p><p><strong>Fix:</strong></p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.local/bin/ps</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Or refresh all shims (removes ps, installs current set):</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">thegent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install-shims</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>Verify:</strong> <code>which ps</code> should show <code>/bin/ps</code> (or <code>/usr/bin/ps</code>), not <code>~/.local/bin/ps</code>.</p><hr><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ol><li><strong>Open a new terminal</strong> (or <code>exec zsh</code>) to pick up the restored config.</li><li><strong>Verify:</strong> <code>codex --help</code> and <code>copilot --help</code> should work without git errors.</li><li><strong>Optional:</strong> Run <code>./scripts/install_zsh_plugins.sh</code> and follow <a href="./guides/SHELL_ZSH_PLUGIN_SETUP.html">SHELL_ZSH_PLUGIN_SETUP.md</a> for fnm/mise, fzf-tab, starship.</li><li><strong>thegent install:</strong> Run <code>thegent install</code> with targets <code>system</code> and <code>user</code> to sync shell files on future updates.</li></ol><hr><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./reference/WORK_STREAM.html">WORK_STREAM.md</a> — canonical backlog</li><li><a href="./plans/00-MASTER-INDEX.html">00-MASTER-INDEX.md</a> — plan index</li></ul>`,53)])])}const g=o(a,[["render",n]]);export{u as __pageData,g as default};
